pet_000597={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="传说它是远古时期坠入卡洛西亚大陆的陨石，被充满魔力的土地赋予了生命。在它身边能测到一片明显异常的引力场，随手扔出的石子也会不由自主地朝它靠拢，所幸大多个体性格温和，是学者们研究地外星体的重要来源。",ecology={activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-09-10 ~ 2026-09-25"}},destined_flower={nature="沉默"},eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的星星眼。",icon="Item_150832.png",name="星星眼的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的星星眼。",icon="Item_150842.png",is_shiny=true,name="异色星星眼的蛋"}},fruits={{description="通过观察其花纹可以看出，这是星星眼的果实。",icon="Item_108090.png",name="星星眼的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={5,11},egg_size={huge_min=178395,max=180000,min=99750,mini_max=101355,unit="g"},evolution_id="evolution_3359b7500103",feature_skill_id="skill_000205",game_id=3236,handbook_id="handbook_000463",handbook_show_topics=true,has_shiny=true,height="0.85~1.22M",id="pet_000597",image={egg="Item_107090.png",fruits={"Item_108090.png"},has_egg=true,has_fruit=true,head="PetAvatar_3236.png",illustration="PetPortrait_img_Ill_QiuQiu1_001_Res.png",shiny="PetPortrait_img_Ill_QiuQiu1_101_Res.png"},learnset_id="learnset_3cfab3d879db",move_type="地面",name="星星眼",number="463",perception_range=40,relation_key="幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=60,review_gold=3000, stats={atk=97,def=116,hp=116,spa=120,spd=71,spe=85},title="星星眼",types={"幻系"},weight="285~450KG"},
pet_000598={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="皇家研究院的旧标本室里，有一只已经风干很久的虫。某天夜里，值班研究员听见木架上传来一声轻轻的\"嗒\"，回头看时，标本针孔里空空如也。从那以后，未完虫学会了绕开所有尖锐的东西走路，遇到危险就地一躺，装作标本。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的未完虫。",icon="Item_150833.png",name="未完虫的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的未完虫。",icon="Item_150846.png",is_shiny=true,name="异色未完虫的蛋"}},fruits={{description="通过观察其花纹可以看出，这是未完虫的果实。",icon="Item_108212.png",name="未完虫的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={4,12},egg_size={huge_min=1150,max=1164,min=420,mini_max=434,unit="g"},evolution_id="evolution_dd47b479f520",feature_skill_id="skill_000203",game_id=3542,handbook_id="handbook_000454",handbook_show_topics=true,has_shiny=true,height="0.1~0.26M",id="pet_000598",image={egg="Item_107242.png",fruits={"Item_108212.png"},has_egg=true,has_fruit=true,head="PetAvatar_3542.png",illustration="PetPortrait_img_Gho_WeiWanChong1_001_Res.png",shiny="PetPortrait_img_Gho_WeiWanChong1_101_Res.png"},learnset_id="learnset_5a018ea812fd",move_type="浮游",name="未完虫",number="454",perception_range=40,relation_key="幽系|虫系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=80,review_gold=4000, stats={atk=102,def=68,hp=86,spa=111,spd=100,spe=100},title="未完虫",types={"幽系","虫系"},weight="1.2~2.91KG"},
pet_000599={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="洛克走过湿地时，会让热团团带路。只有热团团走过的路面踩上去暖和，别的精灵也会沿着这条路暖身子，久而久之就形成了新的路线。热团团不知道这些，缩一团歇着呢。",ecology={eggs={{description="购买「月涌通行证-日之光」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的热团团。",icon="Item_150813.png",is_shiny=true,name="异色热团团的蛋",sources={"购买「月涌通行证-日之光」闪耀契约礼券"}}},fruits={{description="通过观察其花纹可以看出，这是热团团的果实。",icon="Item_108209.png",name="热团团的果实",sources={"月涌通行证获得"},wisdom_tree=false}}},egg_group={1},evolution_id="evolution_53532e27eb34",feature_skill_id="skill_000197",game_id=3574,handbook_id="handbook_000449",handbook_show_topics=true,has_shiny=true,height="0.37~0.51M",id="pet_000599",image={egg="Item_149243.png",fruits={"Item_108209.png"},has_egg=true,has_fruit=true,head="PetAvatar_3574.png",illustration="PetPortrait_img_Fir_ReTuanTuan1_001_Res.png",shiny="PetPortrait_img_Fir_ReTuanTuan1_101_Res.png"},learnset_id="learnset_3d550ce8167a",move_type="浮游",name="热团团",number="449",perception_range=40,relation_key="火系|虫系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=32,review_gold=1600, stats={atk=69,def=72,hp=48,spa=18,spd=72,spe=63},title="热团团",types={"火系","虫系"},weight="4.9~6.5KG"},
pet_000600={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="牧民说只要焰米龙飞过的地方草就长得快，露水干得早，播种能提前半个月，沿线的牧民从小就知道，踩温热地面走夜路不冻脚。焰米龙不知道这些，它们心里只有自己的球。",ecology={acquisition_pet_id="pet_000599"},egg_group={1},evolution_id="evolution_53532e27eb34",feature_skill_id="skill_000197",game_id=3575,handbook_id="handbook_000450",handbook_show_topics=true,has_shiny=true,height="0.69~0.96M",id="pet_000600",image={has_egg=false,has_fruit=false,head="PetAvatar_3575.png",illustration="PetPortrait_img_Fir_ReTuanTuan2_001_Res.png",shiny="PetPortrait_img_Fir_ReTuanTuan2_101_Res.png"},learnset_id="learnset_3d550ce8167a",move_type="浮游",name="焰米龙",number="450",perception_range=40,relation_key="火系|虫系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=56,review_gold=2800, stats={atk=92,def=96,hp=63,spa=23,spd=96,spe=84},title="焰米龙",types={"火系","虫系"},weight="9.65~17.6KG"},
pet_000601={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="传说最早的村镇都挨着圣凯布米龙每天路过的路线建起来，洛克们沿着它留下的温热痕迹耕种、修路。地图上的路，最初就是这么画下来的。如今大部分洛克都不记得这些路是从哪来的，只知道这条路一直比别处暖和。",ecology={acquisition_pet_id="pet_000599"},egg_group={1},evolution_id="evolution_53532e27eb34",feature_skill_id="skill_000197",game_id=3576,handbook_id="handbook_000451",handbook_show_topics=true,has_shiny=true,height="1.35~1.62M",id="pet_000601",image={has_egg=false,has_fruit=false,head="PetAvatar_3576.png",illustration="PetPortrait_img_Fir_ReTuanTuan3_001_Res.png",shiny="PetPortrait_img_Fir_ReTuanTuan3_101_Res.png"},learnset_id="learnset_3d550ce8167a",move_type="浮游",name="圣凯布米龙",number="451",perception_range=40,relation_key="火系|虫系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=3,starlight=80,review_gold=4000, stats={atk=116,def=120,hp=79,spa=29,spd=120,spe=105},title="圣凯布米龙",types={"火系","虫系"},weight="90~130KG"},
pet_000602={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="玳龟自己也搞不懂头骨里的球体是什么，魔法学院图书馆里有本旧书写过一句话：这世界被一只很大的龟驮着，那只龟又被更大的龟驮着，一路往下，数不到头。玳龟不识字，它只是每天慢慢地驮着自己的小球晃悠。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的玳龟。",icon="Item_150834.png",name="玳龟的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的玳龟。",icon="Item_150850.png",is_shiny=true,name="异色玳龟的蛋"}},fruits={{description="通过观察其花纹可以看出，这是玳龟的果实。",icon="Item_108226.png",name="玳龟的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={2,3},egg_size={huge_min=8517,max=8600,min=4445,mini_max=4528,unit="g"},evolution_id="evolution_e5e9584a28c9",feature_skill_id="skill_000206",game_id=3589,handbook_id="handbook_000455",handbook_show_topics=true,has_shiny=true,height="0.37~0.6M",id="pet_000602",image={egg="Item_107243.png",fruits={"Item_108226.png"},has_egg=true,has_fruit=true,head="PetAvatar_3589.png",illustration="PetPortrait_img_Ill_DaiGui1_001_Res.png",shiny="PetPortrait_img_Ill_DaiGui1_101_Res.png"},learnset_id="learnset_16a117108611",move_type="浮游",name="玳龟",number="455",perception_range=40,relation_key="幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=24,review_gold=1200, stats={atk=37,def=58,hp=101,spa=85,spd=93,spe=40},talent_pool_id=1001,title="玳龟",types={"幻系"},weight="12.7~21.5KG"},
pet_000603={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="研究员检测玳塔胸腔中层层嵌套的幻系能量时，往内每深入一层，能量结构就更复杂，直到探测器承受不住而中断记录。而那本书记载乌龟塔理论的书从此被移出寓言分类，重新归档为待验证的世界模型。",ecology={acquisition_pet_id="pet_000602",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-09-25 ~ 2026-10-09"}},destined_flower={nature="沉默"}},egg_group={2,3},egg_size={huge_min=8517,max=8600,min=4445,mini_max=4528,unit="g"},evolution_id="evolution_e5e9584a28c9",feature_skill_id="skill_000206",game_id=3590,handbook_id="handbook_000456",handbook_show_topics=true,has_shiny=true,height="1.08~1.33M",id="pet_000603",image={egg="Item_107243.png",fruits={"Item_108226.png"},has_egg=true,has_fruit=true,head="PetAvatar_3590.png",illustration="PetPortrait_img_Ill_DaiGui2_001_Res.png",shiny="PetPortrait_img_Ill_DaiGui2_101_Res.png"},learnset_id="learnset_16a117108611",move_type="浮游",name="玳塔",number="456",perception_range=40,relation_key="幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=60,review_gold=3000, stats={atk=47,def=72,hp=127,spa=107,spd=116,spe=50},talent_pool_id=1001,title="玳塔",types={"幻系"},weight="43~81.6KG"},
pet_000604={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="据说它们最早是地系研究院造出来测风用的，如今已经形成了自己的族群。它们的身体极轻，风一起头顶的杯子便\"咔哒咔哒\"地转起来，风一停又落回地面。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的量风碗。",icon="Item_150835.png",name="量风碗的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的量风碗。",icon="Item_150851.png",is_shiny=true,name="异色量风碗的蛋"}},fruits={{description="通过观察其花纹可以看出，这是量风碗的果实。",icon="Item_108206.png",name="量风碗的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={4,15},egg_size={huge_min=1445,max=1460,min=665,mini_max=680,unit="g"},evolution_id="evolution_bc04e404baf5",feature_skill_id="skill_000201",game_id=3663,handbook_id="handbook_000457",handbook_show_topics=true,has_shiny=true,height="0.4~0.6M",id="pet_000604",image={egg="Item_107244.png",fruits={"Item_108206.png"},has_egg=true,has_fruit=true,head="PetAvatar_3664.png",illustration="PetPortrait_img_Win_LiangFengWan1_001_Res.png",shiny="PetPortrait_img_Win_LiangFengWan1_101_Res.png"},learnset_id="learnset_8937d853acf7",move_type="浮游",name="量风碗",number="457",perception_range=40,relation_key="翼系|机械系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=24,review_gold=1200, stats={atk=79,def=93,hp=78,spa=77,spd=67,spe=96},title="量风碗",types={"翼系","机械系"},weight="1.9~3.65KG"},
pet_000605={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="测风蝉知道风要从哪边来，也知道风要停多久。研究院早就换上了新一代的电子测风仪，那些造它们的老工程师大多也已经退休了。它们每天照旧停在山口和楼顶，等待着风来，像是在等一个再也不会来的洛克下班。",ecology={acquisition_pet_id="pet_000604",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-10-09 ~ 2026-10-23"}},destined_flower={nature="开朗"}},egg_group={4,15},egg_size={huge_min=1445,max=1460,min=665,mini_max=680,unit="g"},evolution_id="evolution_bc04e404baf5",feature_skill_id="skill_000201",game_id=3664,handbook_id="handbook_000458",handbook_show_topics=true,has_shiny=true,height="1.3~1.6M",id="pet_000605",image={egg="Item_107244.png",fruits={"Item_108206.png"},has_egg=true,has_fruit=true,head="PetAvatar_3663.png",illustration="PetPortrait_img_Win_LiangFengWan2_001_Res.png",shiny="PetPortrait_img_Win_LiangFengWan2_101_Res.png"},learnset_id="learnset_8937d853acf7",move_type="浮游",name="测风蝉",number="458",perception_range=40,relation_key="翼系|机械系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=60,review_gold=3000, stats={atk=98,def=116,hp=98,spa=97,spd=84,spe=120},title="测风蝉",types={"翼系","机械系"},weight="9.9~17KG"},
pet_000606={can_double_ride=true,can_ride=true,class="自然类精灵",description="迷雾森林曾经的原住民，如今已在卡洛西亚大陆几乎绝迹。胸口嵌着一颗黄色宝石，据说封着一股来历不明的力量。它们沉默寡言，独自穿行于林间的雾气之中，遇到别的精灵便远远绕开，一整个白天都说不上一句话。",ecology={eggs={{description="完成「月涌狂想」赛季作业获得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”，且支持自选性格与个体资质、拥有“无畏”特长的诅咒狼灵。",icon="Item_150831.png",name="诅咒狼灵的蛋",sources={"完成「月涌狂想」赛季作业"}}}},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3761,handbook_id="handbook_000443",handbook_show_topics=true,has_shiny=false,height="0.59~0.84M",id="pet_000606",image={egg="Item_150831.png",has_egg=true,has_fruit=false,head="PetAvatar_3759.png",illustration="PetPortrait_img_Wus_LangLing1_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="诅咒狼灵",number="443",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=80,review_gold=4000, stats={atk=77,def=77,hp=69,spa=31,spd=59,spe=78},submit_reward=3000,talent_pool_id=1001,title="诅咒狼灵",types={"幽系","幻系"},weight="8.5~13.3KG"},
pet_000607={can_double_ride=true,can_ride=true,class="自然类精灵",description="在有月亮的夜里，光芒会顺着它们胸前毛发的边缘缓缓流淌。它开始学会踏着月光潜行，落地几乎无声。仍是独来独往，很少与其他精灵哪怕是同族并肩行动，即便在同一片林子里遇见，也只是遥遥对望一眼便各自离开。",ecology={acquisition_pet_id="pet_000606"},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3762,handbook_id="handbook_000444",handbook_show_topics=true,has_shiny=false,height="1.35~1.66M",id="pet_000607",image={has_egg=false,has_fruit=false,head="PetAvatar_3762.png",illustration="PetPortrait_img_Wus_LangLing2_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="新月狼灵",number="444",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=80,review_gold=4000, stats={atk=103,def=102,hp=92,spa=41,spd=78,spe=104},submit_reward=3000,talent_pool_id=1001,title="新月狼灵",types={"幽系","幻系"},weight="30.5~47KG"},
pet_000608={can_double_ride=true,can_ride=true,class="自然类精灵",description="独自行走的离群之狼，月缺时它力量最弱，只是安静地趴在某块山石上休息。月圆那一夜，它会从月光最亮的地方走出来。当你看见银月狼王的时候，它已经看了你很久了，如果挥手打招呼的话，它也只是远远的点头致意。",ecology={acquisition_pet_id="pet_000606"},egg_group={1},evolution_id="evolution_0ed502614ad1",feature_skill_id="skill_000196",game_id=3763,handbook_id="handbook_000445",handbook_show_topics=true,has_shiny=false,height="1.73~2.05M",id="pet_000608",image={has_egg=false,has_fruit=false,head="PetAvatar_3763.png",illustration="PetPortrait_img_Wus_LangLing3_001_Res.png"},learnset_id="learnset_162b16b43e43",move_type="地面",name="银月狼王",number="445",perception_range=40,relation_key="幽系|幻系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=3,starlight=80,review_gold=4000, stats={atk=128,def=128,hp=115,spa=51,spd=98,spe=130},submit_reward=3000,talent_pool_id=1001,title="银月狼王",types={"幽系","幻系"},weight="77~115KG"},
pet_000609={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="月光下很难看到新月鹭，它们会融入月光在水面的倒影里，啄水里的月光。月亮躲进云里时，才发现岸边一直站着一只缩着脖子的新月鹭，好像刚才什么都没发生。",ecology={eggs={{description="购买「月涌通行证-月之华」闪耀契约礼券获得的珍贵精灵蛋，经过孵化可以得到“异色”外观、“了不起”天分、且支持自选性格、个体资质的新月鹭。",icon="Item_150812.png",is_shiny=true,name="异色新月鹭的蛋",sources={"购买「月涌通行证-月之华」闪耀契约礼券"}}},fruits={{description="通过观察其花纹可以看出，这是新月鹭的果实。",icon="Item_108202.png",name="新月鹭的果实",sources={"月涌通行证获得"},wisdom_tree=false}}},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3764,handbook_id="handbook_000446",handbook_show_topics=true,has_shiny=true,height="0.46~0.6M",id="pet_000609",image={egg="Item_149247.png",fruits={"Item_108202.png"},has_egg=true,has_fruit=true,head="PetAvatar_3764.png",illustration="PetPortrait_img_Win_XinYueLu1_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu1_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="新月鹭",number="446",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=32,review_gold=1600, stats={atk=59,def=62,hp=50,spa=60,spd=68,spe=69},submit_reward=3000,talent_pool_id=1001,title="新月鹭",types={"翼系","冰系"},weight="3.7~5KG"},
pet_000610={can_double_ride=true,can_ride=true,catch_threshold={500},class="自然类精灵",description="月辉鹭蹲在水面的月亮倒影上，一动不动，就像在孵月亮。有的洛克相信月亮发光不是因为月亮自己会发光，是因为有月辉鹭蹲着把光芒传输给月亮，也有洛克持相反态度。",ecology={acquisition_pet_id="pet_000609"},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3765,handbook_id="handbook_000447",handbook_show_topics=true,has_shiny=true,height="0.82~1.13M",id="pet_000610",image={has_egg=false,has_fruit=false,head="PetAvatar_3765.png",illustration="PetPortrait_img_Win_XinYueLu2_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu2_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="月辉鹭",number="447",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=56,review_gold=2800, stats={atk=79,def=83,hp=66,spa=80,spd=90,spe=92},submit_reward=3000,talent_pool_id=1001,title="月辉鹭",types={"翼系","冰系"},weight="6.83~9.7KG"},
pet_000611={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="月使鹭纳出没的地方，天上的月亮只剩一道细弧。月光全在它们身上，它们是这片湖区最亮的夜晚光源。等到它们换羽的日子，羽毛上的月光会跟着脱落，洒回天上，月亮又会重新变圆。",ecology={acquisition_pet_id="pet_000609"},egg_group={1},evolution_id="evolution_3d0cc5393c1a",feature_skill_id="skill_000198",game_id=3766,handbook_id="handbook_000448",handbook_show_topics=true,has_shiny=true,height="1.71~1.94M",id="pet_000611",image={has_egg=false,has_fruit=false,head="PetAvatar_3766.png",illustration="PetPortrait_img_Win_XinYueLu3_001_Res.png",shiny="PetPortrait_img_Win_XinYueLu3_101_Res.png"},learnset_id="learnset_da630e35c0e9",move_type="地面",name="月使鹭纳",number="448",perception_range=40,relation_key="翼系|冰系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=3,starlight=80,review_gold=4000, stats={atk=99,def=104,hp=83,spa=100,spd=113,spe=115},submit_reward=3000,talent_pool_id=1001,title="月使鹭纳",types={"翼系","冰系"},weight="41~75.8KG"},
pet_000612={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="章脑丸思考的时候，半透明的身体里会有一小串光顺着神经一节一节亮过去，它们总是成群漂在近岸的浅水里，小脑袋一起明明灭灭，那是它们在聊天。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的章脑丸。",icon="Item_150836.png",name="章脑丸的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的章脑丸。",icon="Item_150853.png",is_shiny=true,name="异色章脑丸的蛋"}},fruits={{description="通过观察其花纹可以看出，这是章脑丸的果实。",icon="Item_108205.png",name="章脑丸的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7,10},egg_size={huge_min=1246,max=1260,min=525,mini_max=539,unit="g"},evolution_id="evolution_b13349d01c38",feature_skill_id="skill_000200",game_id=3767,handbook_id="handbook_000452",handbook_show_topics=true,has_shiny=true,height="0.59~0.9M",id="pet_000612",image={egg="Item_107245.png",fruits={"Item_108205.png"},has_egg=true,has_fruit=true,head="PetAvatar_3767.png",illustration="PetPortrait_img_Lig_ZhangNaoWan1_001_Res.png",shiny="PetPortrait_img_Lig_ZhangNaoWan1_101_Res.png"},learnset_id="learnset_1828f13f54f1",move_type="地面",name="章脑丸",number="452",perception_range=40,relation_key="光系|水系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=32,review_gold=1600, stats={atk=42,def=69,hp=89,spa=99,spd=99,spe=80},submit_reward=3000,talent_pool_id=1001,title="章脑丸",types={"光系","水系"},weight="1.5~3.15KG"},
pet_000613={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="极聪明的精灵，无数光点从四周向智辉章脑汇聚，又从它这里散回四周，族群里所有的所见所感，最终都汇入它的脑中。它们偏爱有洛克生活的水域，能理解洛克说话的语气。",ecology={acquisition_pet_id="pet_000612",activities={{name="命定花种",note="花种出没·战斗后可捕捉",window="2026-09-10 ~ 2026-09-25"}},destined_flower={nature="胆小"}},egg_group={7,10},egg_size={huge_min=1246,max=1260,min=525,mini_max=539,unit="g"},evolution_id="evolution_b13349d01c38",feature_skill_id="skill_000200",game_id=3768,handbook_id="handbook_000453",handbook_show_topics=true,has_shiny=true,height="1.53~1.7M",id="pet_000613",image={egg="Item_107245.png",fruits={"Item_108205.png"},has_egg=true,has_fruit=true,head="PetAvatar_3768.png",illustration="PetPortrait_img_Lig_ZhangNaoWan3_001_Res.png",shiny="PetPortrait_img_Lig_ZhangNaoWan3_101_Res.png"},learnset_id="learnset_1828f13f54f1",move_type="地面",name="智辉章脑",number="453",perception_range=40,relation_key="光系|水系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=80,review_gold=4000, stats={atk=53,def=87,hp=112,spa=123,spd=124,spe=100},submit_reward=3000,talent_pool_id=1001,title="智辉章脑",types={"光系","水系"},weight="6~9.9KG"},
pet_000614={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="洛克大道上打翻的垃圾桶、面包店里少了一半的糕点、驻地里凭空消失的徽章，十有八九是这些小家伙干的。它们从不单独行动，三两成群蹲在街角盯梢，看见落单的精灵和洛克便一拥而上。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的小浣蛋。",icon="Item_150837.png",name="小浣蛋的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的小浣蛋。",icon="Item_150854.png",is_shiny=true,name="异色小浣蛋的蛋"}},fruits={{description="通过观察其花纹可以看出，这是小浣蛋的果实。",icon="Item_108214.png",name="小浣蛋的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={6,9},egg_size={huge_min=1424,max=1440,min=630,mini_max=646,unit="g"},evolution_id="evolution_23a784dc26f1",feature_skill_id="skill_000202",game_id=3771,handbook_id="handbook_000459",handbook_show_topics=true,has_shiny=true,height="0.28~0.45M",id="pet_000614",image={egg="Item_107246.png",fruits={"Item_108214.png"},has_egg=true,has_fruit=true,head="PetAvatar_3771.png",illustration="PetPortrait_img_Dem_XiaoHuanDan1_001_Res.png",shiny="PetPortrait_img_Dem_XiaoHuanDan1_101_Res.png"},learnset_id="learnset_aac3cf890bff",move_type="地面",name="小浣蛋",number="459",perception_range=40,relation_key="恶系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=32,review_gold=1600, stats={atk=93,def=99,hp=78,spa=88,spd=92,spe=96},submit_reward=3000,talent_pool_id=1001,title="小浣蛋",types={"恶系"},weight="1.8~3.6KG"},
pet_000615={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="每一群小浣蛋背后都跟着一只黑手浣熊，翻垃圾桶它先翻，新鲜的垃圾它先吃。黑手浣熊对体型更大的精灵大哥很有礼貌低头哈腰，尾巴摇得飞起，转头就打个手势让小浣蛋们偷偷去掏大哥的家底。",ecology={acquisition_pet_id="pet_000614"},egg_group={6,9},egg_size={huge_min=1424,max=1440,min=630,mini_max=646,unit="g"},evolution_id="evolution_23a784dc26f1",feature_skill_id="skill_000202",game_id=3772,handbook_id="handbook_000460",handbook_show_topics=true,has_shiny=true,height="0.56~0.8M",id="pet_000615",image={egg="Item_107246.png",fruits={"Item_108214.png"},has_egg=true,has_fruit=true,head="PetAvatar_3772.png",illustration="PetPortrait_img_Dem_XiaoHuanDan2_001_Res.png",shiny="PetPortrait_img_Dem_XiaoHuanDan2_101_Res.png"},learnset_id="learnset_aac3cf890bff",move_type="地面",name="黑手浣熊",number="460",perception_range=40,relation_key="恶系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=80,review_gold=4000, stats={atk=116,def=124,hp=97,spa=110,spd=115,spe=120},submit_reward=3000,talent_pool_id=1001,title="黑手浣熊",types={"恶系"},weight="4.5~10.5KG"},
pet_000616={can_double_ride=true,can_ride=true,catch_threshold={1000},class="自然类精灵",description="洛克走过废弃的旧宅，忽然听到铃声在耳边响起，回头却什么也看不见，大多是幽铃藏在墙角恶作剧。它们并不真的想吓着谁，只是喜欢看洛克东张西望找不着的样子。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的幽铃。",icon="Item_150838.png",name="幽铃的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的幽铃。",icon="Item_150855.png",is_shiny=true,name="异色幽铃的蛋"}},fruits={{description="通过观察其花纹可以看出，这是幽铃的果实。",icon="Item_108221.png",name="幽铃的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7,12},egg_size={huge_min=791,max=800,min=332,mini_max=341,unit="g"},evolution_id="evolution_bacfc388de61",feature_skill_id="skill_000204",game_id=3773,handbook_id="handbook_000461",handbook_show_topics=true,has_shiny=true,height="0.4~0.55M",id="pet_000616",image={egg="Item_107247.png",fruits={"Item_108221.png"},has_egg=true,has_fruit=true,head="PetAvatar_3773.png",illustration="PetPortrait_img_Gho_YouLing1_001_Res.png",shiny="PetPortrait_img_Gho_YouLing1_101_Res.png"},learnset_id="learnset_76a86cb172ea",move_type="地面",name="幽铃",number="461",perception_range=40,relation_key="幽系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=24,review_gold=1200, stats={atk=37,def=80,hp=99,spa=93,spd=105,spe=76},submit_reward=3000,talent_pool_id=1001,title="幽铃",types={"幽系"},weight="0.95~2KG"},
pet_000617={can_double_ride=true,can_ride=true,catch_threshold={250},class="自然类精灵",description="成长后恶作剧也升了级，它会招呼一群幽铃埋伏在旧宅子的各个角落，等洛克推门进来，就四处发出声音，把洛克吵得团团转，自己却都不露面。被吓的洛克若是不生气，它们便会觉得有点没意思，悻悻地散去。",ecology={acquisition_pet_id="pet_000616"},egg_group={7,12},egg_size={huge_min=791,max=800,min=332,mini_max=341,unit="g"},evolution_id="evolution_bacfc388de61",feature_skill_id="skill_000204",game_id=3774,handbook_id="handbook_000462",handbook_show_topics=true,has_shiny=true,height="1.05~1.37M",id="pet_000617",image={egg="Item_107247.png",fruits={"Item_108221.png"},has_egg=true,has_fruit=true,head="PetAvatar_3774.png",illustration="PetPortrait_img_Gho_YouLing3_001_Res.png",shiny="PetPortrait_img_Gho_YouLing3_101_Res.png"},learnset_id="learnset_76a86cb172ea",move_type="地面",name="摇铃魔偶",number="462",perception_range=40,relation_key="幽系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=60,review_gold=3000, stats={atk=46,def=99,hp=123,spa=117,spd=131,spe=95},submit_reward=3000,talent_pool_id=1001,title="摇铃魔偶",types={"幽系"},weight="4.73~8.9KG"},
pet_000618={can_double_ride=false,can_ride=true,catch_threshold={1000},class="自然类精灵",description="布灵的样子是一只手工缝的小熊，真正的它其实是从熊头顶露出来的那一小团黄色能量，布偶只是它给自己找的一个不那么显眼的壳。据说它的家乡是一片被黑暗吃掉过的星空，所以它到现在都怕黑。",ecology={eggs={{description="在「月涌狂想」赛季的代币商店内购得的珍贵精灵蛋，经过孵化可以得到“完美无瑕”、且支持自选性格与个体资质的布灵。",icon="Item_150839.png",name="布灵的蛋"},{description="经过孵化可以得到“异色”外观、“了不起”天分的布灵。",icon="Item_150856.png",is_shiny=true,name="异色布灵的蛋"}},fruits={{description="通过观察其花纹可以看出，这是布灵的果实。",icon="Item_108241.png",name="布灵的果实",sources={"完成赛季作业挑战课题"},wisdom_tree=false}}},egg_group={7},egg_size={huge_min=1144,max=1160,min=350,mini_max=366,unit="g"},evolution_id="evolution_16cfea3594a0",feature_skill_id="skill_000207",game_id=3775,handbook_id="handbook_000464",handbook_show_topics=true,has_shiny=true,height="0.38~0.51M",id="pet_000618",image={egg="Item_107248.png",fruits={"Item_108241.png"},has_egg=true,has_fruit=true,head="PetAvatar_3775.png",illustration="PetPortrait_img_Ill_BuLing1_001_Res.png",shiny="PetPortrait_img_Ill_BuLing1_101_Res.png"},learnset_id="learnset_7ecee35fafd0",move_type="地面",name="布灵",number="464",perception_range=40,relation_key="幻系|光系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=1,starlight=24,review_gold=1200, stats={atk=92,def=98,hp=66,spa=32,spd=77,spe=100},submit_reward=3000,talent_pool_id=1001,title="布灵",types={"幻系","光系"},weight="1~2.9KG"},
pet_000619={can_double_ride=false,can_ride=true,catch_threshold={250},class="自然类精灵",description="布灵布灵对太阳和月亮没什么感觉，它们家乡的星空曾经比这里的更亮更大，可惜后来都熄灭了。它们真正着迷的是洛造光源，天一黑，它们会从街角、屋檐下、井盖缝里一个个悄悄冒出来，围着灯柱看很久很久。",ecology={acquisition_pet_id="pet_000618"},egg_group={7},egg_size={huge_min=1144,max=1160,min=350,mini_max=366,unit="g"},evolution_id="evolution_16cfea3594a0",feature_skill_id="skill_000207",game_id=3776,handbook_id="handbook_000465",handbook_show_topics=true,has_shiny=true,height="0.65~0.87M",id="pet_000619",image={egg="Item_107248.png",fruits={"Item_108241.png"},has_egg=true,has_fruit=true,head="PetAvatar_3776.png",illustration="PetPortrait_img_Ill_BuLing2_001_Res.png",shiny="PetPortrait_img_Ill_BuLing2_101_Res.png"},learnset_id="learnset_7ecee35fafd0",move_type="地面",name="布灵布灵",number="465",perception_range=40,relation_key="幻系|光系",release={date="2026-09-10",version="1.1.1"},siblings={},stage=2,starlight=60,review_gold=3000, stats={atk=115,def=123,hp=83,spa=40,spd=96,spe=125},submit_reward=3000,talent_pool_id=1001,title="布灵布灵",types={"幻系","光系"},weight="3.3~6.7KG"}
